"use strict";(globalThis.webpackChunkspec_bright_website=globalThis.webpackChunkspec_bright_website||[]).push([[3570],{581(e){e.exports=JSON.parse('{"version":{"pluginId":"jbehave-for-jira","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"docs":[{"type":"link","href":"/docs/jbehave-for-jira/","label":"Introduction","docId":"intro","unlisted":false},{"type":"category","label":"Features","collapsible":true,"collapsed":true,"items":[{"type":"category","label":"Advanced","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/docs/jbehave-for-jira/features/advanced/exporting-to-xml-csv-and-word","label":"Exporting to XML, CSV and Word","docId":"features/advanced/exporting-to-xml-csv-and-word","unlisted":false},{"type":"link","href":"/docs/jbehave-for-jira/features/advanced/jira-activity-stream-integration","label":"Jira Activity Stream Integration","docId":"features/advanced/jira-activity-stream-integration","unlisted":false},{"type":"link","href":"/docs/jbehave-for-jira/features/advanced/jql-searching-by-story-execution-status","label":"JQL Searching by Story Execution Status","docId":"features/advanced/jql-searching-by-story-execution-status","unlisted":false},{"type":"link","href":"/docs/jbehave-for-jira/features/advanced/support-for-gherkin-syntax","label":"Support for Gherkin Syntax","docId":"features/advanced/support-for-gherkin-syntax","unlisted":false}],"href":"/docs/jbehave-for-jira/features/advanced/"},{"type":"category","label":"Core","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/docs/jbehave-for-jira/features/core/autocompletion-for-step-parameters","label":"Autocompletion for step parameters","docId":"features/core/autocompletion-for-step-parameters","unlisted":false},{"type":"link","href":"/docs/jbehave-for-jira/features/core/autocompletion-for-steps","label":"Autocompletion for steps","docId":"features/core/autocompletion-for-steps","unlisted":false},{"type":"link","href":"/docs/jbehave-for-jira/features/core/automatic-alignment-of-tabular-parameter-fields","label":"Automatic alignment of tabular parameter fields","docId":"features/core/automatic-alignment-of-tabular-parameter-fields","unlisted":false},{"type":"link","href":"/docs/jbehave-for-jira/features/core/semantic-error-checking","label":"Semantic error checking","docId":"features/core/semantic-error-checking","unlisted":false},{"type":"link","href":"/docs/jbehave-for-jira/features/core/step-patterns-management","label":"Step patterns management","docId":"features/core/step-patterns-management","unlisted":false},{"type":"link","href":"/docs/jbehave-for-jira/features/core/story-execution-reports","label":"Story execution reports","docId":"features/core/story-execution-reports","unlisted":false},{"type":"link","href":"/docs/jbehave-for-jira/features/core/story-history-panel","label":"Story history panel","docId":"features/core/story-history-panel","unlisted":false},{"type":"link","href":"/docs/jbehave-for-jira/features/core/story-syntax-checking","label":"Story syntax checking","docId":"features/core/story-syntax-checking","unlisted":false},{"type":"link","href":"/docs/jbehave-for-jira/features/core/syntax-highlighting","label":"Syntax highlighting","docId":"features/core/syntax-highlighting","unlisted":false},{"type":"link","href":"/docs/jbehave-for-jira/features/core/two-way-git-synchronisation","label":"Two-way Git synchronisation","docId":"features/core/two-way-git-synchronisation","unlisted":false}],"href":"/docs/jbehave-for-jira/features/core/"}],"href":"/docs/jbehave-for-jira/features/"},{"type":"category","label":"Installation","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/docs/jbehave-for-jira/installation/installing-the-plugin","label":"Installing the plugin","docId":"installation/installing-the-plugin","unlisted":false},{"type":"link","href":"/docs/jbehave-for-jira/installation/integrating-with-your-ci-build","label":"Integrating with your CI build","docId":"installation/integrating-with-your-ci-build","unlisted":false}],"href":"/docs/jbehave-for-jira/installation/"},{"type":"link","href":"/docs/jbehave-for-jira/overview","label":"Overview","docId":"overview","unlisted":false},{"type":"category","label":"Support","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/docs/jbehave-for-jira/support/end-user-license-agreement","label":"End User License Agreement","docId":"support/end-user-license-agreement","unlisted":false},{"type":"link","href":"/docs/jbehave-for-jira/support/issue-tracking","label":"Issue Tracking","docId":"support/issue-tracking","unlisted":false},{"type":"link","href":"/docs/jbehave-for-jira/support/privacy-and-security","label":"Privacy and Security","docId":"support/privacy-and-security","unlisted":false},{"type":"link","href":"/docs/jbehave-for-jira/support/support-service-level-agreement","label":"Support Service Level Agreement","docId":"support/support-service-level-agreement","unlisted":false},{"type":"category","label":"Troubleshooting","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/docs/jbehave-for-jira/support/troubleshooting/enable-debug-logging-in-browser","label":"Enable Debug Logging in Browser","docId":"support/troubleshooting/enable-debug-logging-in-browser","unlisted":false}],"href":"/docs/jbehave-for-jira/support/troubleshooting/"}],"href":"/docs/jbehave-for-jira/support/"},{"type":"category","label":"Tips & Tricks","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/docs/jbehave-for-jira/tips-and-tricks/disable-uploading-of-step-patterns-from-ci-server","label":"Disable Uploading of Step Patterns from CI Server","docId":"tips-and-tricks/disable-uploading-of-step-patterns-from-ci-server","unlisted":false},{"type":"link","href":"/docs/jbehave-for-jira/tips-and-tricks/turn-features-on-off","label":"Turn Features On / Off","docId":"tips-and-tricks/turn-features-on-off","unlisted":false}],"href":"/docs/jbehave-for-jira/tips-and-tricks/"}]},"docs":{"features/advanced/exporting-to-xml-csv-and-word":{"id":"features/advanced/exporting-to-xml-csv-and-word","title":"Exporting to XML, CSV and Word","description":"The plugin comes with a custom field called \'Story Field\' that allows the story entered via the story section on the view issue page to be exported into XML, CSV, Word and other formats using standard Jira functionality while on the browse/search for issues page.","sidebar":"docs"},"features/advanced/index":{"id":"features/advanced/index","title":"Advanced","description":"","sidebar":"docs"},"features/advanced/jira-activity-stream-integration":{"id":"features/advanced/jira-activity-stream-integration","title":"Jira Activity Stream Integration","description":"To support tracking of changes made to the JBehave stories the plugin provides integration with the Jira\'s activity stream functionality, where each change to a given story would appear as a separate activity entry under the \\"Activity\\" tab on the view issue page. The activity entry contains the updated story content along with the time when the change was made and also the author of the change.","sidebar":"docs"},"features/advanced/jql-searching-by-story-execution-status":{"id":"features/advanced/jql-searching-by-story-execution-status","title":"JQL Searching by Story Execution Status","description":"The plugin comes with a custom field named \'Story Status Field\' which holds the last execution status of the attached JBehave story (passed, failed, etc.) that can be used as part of JQL criteria while searching for issues.\xa0You must add this custom field first before you can use it via the issue field configuration screen in the Jira administration area as you would with any other custom field.","sidebar":"docs"},"features/advanced/support-for-gherkin-syntax":{"id":"features/advanced/support-for-gherkin-syntax","title":"Support for Gherkin Syntax","description":"JBehave stories are normally written using JBehave syntax where the requirement is expressed in the Narrative section using \'In order to\', \'As a\', \'I want to\' construct however it additionally supports writing stories in a more Cucumber like syntax where a Feature keyword at the top of the story file is used to capture the requirement rather than the Narrative keyword and also the use of some of the other keywords differ, for example the use of Background keyword instead of Lifecycle. See more information in the official JBehave documentation here.","sidebar":"docs"},"features/core/autocompletion-for-step-parameters":{"id":"features/core/autocompletion-for-step-parameters","title":"Autocompletion for step parameters","description":"Autocompletion feature also works when specifying values for step parameters where parameter type is set to accept one of the predefined set of possible values i.e. \'one of\' parameter type in GUI or enum in Java source code.","sidebar":"docs"},"features/core/autocompletion-for-steps":{"id":"features/core/autocompletion-for-steps","title":"Autocompletion for steps","description":"Story editor panel has built-in auto completion support for existing steps so you will never need to remember, guess or refer to your source code to find out what steps exactly are available that you can use for your new story or scenario. To use it simply begin a new line with a step keyword (Given/When/Then) followed by space and then hit Ctr+Space on your keyboard to bring up the drop down menu that shows you all available steps that you can use by simply clicking on it with your mouse or using arrow keys on the keyboard to select the required step followed by Enter add it inline.","sidebar":"docs"},"features/core/automatic-alignment-of-tabular-parameter-fields":{"id":"features/core/automatic-alignment-of-tabular-parameter-fields","title":"Automatic alignment of tabular parameter fields","description":"When using BDD you are very frequently using tabular parameters, i.e. multi line parameters where all columns are separated with a \'|\' character. When you write a story using just a regular text editor these tabular parameters become very tedious to align. When using the JBehaveForJira plugin these parameters are automatically aligned as you type. In the screenshot below we\'ve entered a very long book title on row 4, note however that the columns of the header row and the two data rows above it were aligned automatically.","sidebar":"docs"},"features/core/index":{"id":"features/core/index","title":"Core","description":"","sidebar":"docs"},"features/core/semantic-error-checking":{"id":"features/core/semantic-error-checking","title":"Semantic error checking","description":"As well as checking for syntax errors explained in the earlier section the integrated story editor additionally checks for semantic story errors as you type, which helps you further to write the story correctly the first time round. This semantic error checking is primarily applied to step pattern parameters, or rather values that you specify for them as you write the story. So for example if you are trying to make use of an existing step that was created earlier which has one parameter of type Number and if you were trying to specify a String value for that parameter the editor would highlight this error and show a relevant error message when you drag your mouse over the error icon shown on the left to where the error was found.","sidebar":"docs"},"features/core/step-patterns-management":{"id":"features/core/step-patterns-management","title":"Step patterns management","description":"The plugin comes with complete step patterns management capabilities, which means it provides you with a built in editor to view, add, edit, delete and group existing step patterns so that you can easily know what step patterns you can reuse when writing your future user stories. To bring up the step patterns editor, simply click on the button shown by the arrow in the screenshot below.","sidebar":"docs"},"features/core/story-execution-reports":{"id":"features/core/story-execution-reports","title":"Story execution reports","description":"Once you have written a story with the help of the JBehaveForJira plugin you then want to run it and see the execution result / execution report. This is shown in a another tab on the view issue page provided by the plugin titled Story Execution Reports. The execution report shows you the number of scenarios passed, failed and pending in the header of the tab using differently coloured\xa0text lozenges providing a quick overview of the overall result.","sidebar":"docs"},"features/core/story-history-panel":{"id":"features/core/story-history-panel","title":"Story history panel","description":"Note - that this feature is only enabled if you choose to use Git for storage, see more on the Two-way Git synchronisation page.","sidebar":"docs"},"features/core/story-syntax-checking":{"id":"features/core/story-syntax-checking","title":"Story syntax checking","description":"The user story editor contains built in story syntax validator that checks for any structural or syntax errors as you type. It will highlight things such errors as for example if you try to write a Scenario before Narrative section or if you are missing Examples table following Scenario Outline section or simply make a type in a keyword. The editor would highlight the error by adding a red underscore where the mistake is and additionally will display a round red icon on the left against the line where the error is found. If you hover over with your mouse over this icon a pop up message will be shown with some further information explaining the error.","sidebar":"docs"},"features/core/syntax-highlighting":{"id":"features/core/syntax-highlighting","title":"Syntax highlighting","description":"Story tab that is added by the plugin provides a story editor with built-in syntax highlighting of the different keywords and sections of a JBehave story. This makes stories easy to write and read. The syntax highlighting works as you are writing the story, so no need to switch between edit/view modes in order to see the highlighted keywords, it\'s there as you type.","sidebar":"docs"},"features/core/two-way-git-synchronisation":{"id":"features/core/two-way-git-synchronisation","title":"Two-way Git synchronisation","description":"Starting from plugin version 3.0.0 it is possible to use Git for saving stories into a remote Git repository. The plugin supports pulling down as well as pushing up the changes, hence achieving a two-way synchronisation with the remote Git repository. This is useful as some of your more technical team members may wish to commit further changes to stories directly from their IDEs as they work on implementing the functionality.","sidebar":"docs"},"features/index":{"id":"features/index","title":"Features","description":"","sidebar":"docs"},"installation/index":{"id":"installation/index","title":"Installation","description":"","sidebar":"docs"},"installation/installing-the-plugin":{"id":"installation/installing-the-plugin","title":"Installing the plugin","description":"On this page you will find steps required to:","sidebar":"docs"},"installation/integrating-with-your-ci-build":{"id":"installation/integrating-with-your-ci-build","title":"Integrating with your CI build","description":"Bullet list The JBehaveForJira plugin allows Jira users to write stories directly via the Jira\'s web interface. Once a story is written you would then want to run it and see the execution result directly in Jira also. For this to happen you need to integrate your testing code with the Jira plugin. To do this you need to first download and install the client library of the JBehaveForJira plugin\xa0and then update your testing code to use classes from this client library instead of the default ones provided by the JBehave library. This page describes how to accomplish these two steps. At the bottom of the page there is a link to an example project which you can use as reference.","sidebar":"docs"},"intro":{"id":"intro","title":"Introduction","description":"A BDD tool that everyone on your team can use.","sidebar":"docs"},"overview":{"id":"overview","title":"Overview","description":"How it works:","sidebar":"docs"},"support/end-user-license-agreement":{"id":"support/end-user-license-agreement","title":"End User License Agreement","description":"This agreement governs your trial and continued use of the JBehave For Jira Atlassian Marketplace Product provided by Maryna Prystrom on the Atlassian Marketplace. This product hereinafter is referred to as the App and Maryna Prystrom hereinafter is referred to as the Vendor.","sidebar":"docs"},"support/index":{"id":"support/index","title":"Support","description":"","sidebar":"docs"},"support/issue-tracking":{"id":"support/issue-tracking","title":"Issue Tracking","description":"Currently open issues -\xa0https://jirabdd.atlassian.net/issues/?jql=filter+%3D+%22Filter+for+JBSUP+board%22++and+status+%21%3D+Done+","sidebar":"docs"},"support/privacy-and-security":{"id":"support/privacy-and-security","title":"Privacy and Security","description":"This page describes what private and secret data is accessed or stored by the plugin and for what purposes.","sidebar":"docs"},"support/support-service-level-agreement":{"id":"support/support-service-level-agreement","title":"Support Service Level Agreement","description":"This agreement covers support for JBehave for Jira Add-On. The support can be provided to customers that purchased the Add-On via Atlassian Marketplace. This agreement may be revised.","sidebar":"docs"},"support/troubleshooting/enable-debug-logging-in-browser":{"id":"support/troubleshooting/enable-debug-logging-in-browser","title":"Enable Debug Logging in Browser","description":"For cases when you might experience a UI related issue we are likely going to ask you to provide a Debug level log output from your browser, so that we can get more detailed information as to what might be happening. The debug level is turned off by default and needs to be turned on via the plugin configuration page, see how to access configuration page Turn Features On / Off.","sidebar":"docs"},"support/troubleshooting/index":{"id":"support/troubleshooting/index","title":"Troubleshooting","description":"","sidebar":"docs"},"tips-and-tricks/disable-uploading-of-step-patterns-from-ci-server":{"id":"tips-and-tricks/disable-uploading-of-step-patterns-from-ci-server","title":"Disable Uploading of Step Patterns from CI Server","description":"The plugin offers you two ways to create and maintain step patterns that you use in your story writing:","sidebar":"docs"},"tips-and-tricks/index":{"id":"tips-and-tricks/index","title":"Tips & Tricks","description":"Umbrella page for any tips and tricks.","sidebar":"docs"},"tips-and-tricks/turn-features-on-off":{"id":"tips-and-tricks/turn-features-on-off","title":"Turn Features On / Off","description":"The plugin features and behaviour are customisable on a per Jira project basis, such that turning a feature on or off in one project does not affect the behaviour of that feature in other Jira projects where the plugin may be used.","sidebar":"docs"}}}}')}}]);